package vn.eventplatform.ad.repository; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import vn.eventplatform.ad.domain.Banner; import java.time.LocalDateTime; import java.util.*; public interface BannerRepository extends JpaRepository<Banner,UUID>{ @Query("select b from Banner b where b.active=true and b.campaign.status='APPROVED' and b.startsAt<=:now and b.endsAt>:now order by b.priority desc, b.createdAt desc") List<Banner> findPublic(@Param("now") LocalDateTime now);}
